const item = $input.first();
const candidates = item.json.candidates || [];
const aiText = candidates[0]?.content?.parts?.[0]?.text || '';
const finishReason = candidates[0]?.finishReason || 'UNKNOWN';

const fileName = $('Extract Text Content').first().json.fileName;
const quizTitle = $('Extract Text Content').first().json.quizTitle;
const description = $('Extract Text Content').first().json.description;

if (!aiText) {
  throw new Error(`Gemini không trả về nội dung cho file ${fileName}. Finish reason: ${finishReason}`);
}

let parsedData;
let cleanResponse = aiText.replace(/^```json\s*/m, '').replace(/```\s*$/m, '').trim();

function repairAndParseJSON(str) {
  try {
    return JSON.parse(str);
  } catch (e) {
    let repairedStr = str;

    // 1. Find the boundary between completed questions
    let lastBoundary = repairedStr.lastIndexOf('},{');
    if (lastBoundary === -1) lastBoundary = repairedStr.lastIndexOf('}, {');
    if (lastBoundary === -1) lastBoundary = repairedStr.lastIndexOf('},\n');

    if (lastBoundary !== -1) {
      repairedStr = repairedStr.substring(0, lastBoundary + 1);
      try {
        return JSON.parse(repairedStr + ']}');
      } catch (err) {}
    }

    // 2. If standard repair fails, use regex to salvage ALL complete questions
    const questions = [];
    const regex = /{"question"\s*:\s*".+?"explanation"\s*:\s*"[^"]*"}/gs;
    let match;
    while ((match = regex.exec(str)) !== null) {
      try {
        questions.push(JSON.parse(match[0]));
      } catch(err) {}
    }
    if (questions.length > 0) return { questions };

    // Append original error with more context
    e.message = `${e.message} | Finish reason: ${finishReason}`;
    throw e;
  }
}

try {
  parsedData = repairAndParseJSON(cleanResponse);
} catch (e) {
  throw new Error(`Không thể parse Gemini response cho file ${fileName}\nLỗi: ${e.message}\nNội dung bị lỗi (500 chars): ${cleanResponse.substring(0, 500)}`);
}

let questions = [];
if (Array.isArray(parsedData)) {
  questions = parsedData;
} else if (parsedData.questions && Array.isArray(parsedData.questions)) {
  questions = parsedData.questions;
} else if (parsedData.quiz && Array.isArray(parsedData.quiz)) {
  questions = parsedData.quiz; 
} else {
  for (const key in parsedData) {
    if (Array.isArray(parsedData[key])) {
      questions = parsedData[key];
      break;
    }
  }
}

if (questions.length === 0) {
  throw new Error(`Gemini trả về JSON nhưng không có câu hỏi nào hoàn chỉnh! Finish reason: ${finishReason}`);
}

return [{
  json: {
    fileName,
    quizTitle,
    description,
    questions,
    totalQuestions: questions.length,
    totalFiles: 1
  }
}];

const createResponse = $input.first().json.body || $input.first().json;
const quizData = $('Parse AI Quiz Response').first().json;

const formId = createResponse.formId;
const formUrl = createResponse.responderUri;

if (!formId) {
  throw new Error('Không thể tạo Google Form: ' + JSON.stringify(createResponse));
}

return [{
  json: {
    formId,
    formUrl,
    editUrl: `https://docs.google.com/forms/d/${formId}/edit`,
    quizTitle: quizData.quizTitle,
    questions: quizData.questions,
    totalQuestions: quizData.totalQuestions,
    totalFiles: quizData.totalFiles,
    description: quizData.description
  }
}];

